/// Store content and return a cache entry.
///
/// Uses atomic writes (write-to-temp-then-rename) to prevent corruption
/// when multiple tool installations run concurrently. Content is written
/// before metadata so that if metadata exists, the content is guaranteed
/// to be complete.
pub fn store(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
    ttl_seconds: u64,
) -> Result<CacheEntry> {
    self.ensure_dir()?;

    let content_path = self.content_path(source_id, template_name);
    atomic_write(&content_path, content.as_bytes())?;

    let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
        .with_size(content.len() as u64);

    self.save_metadata(&entry)?;

    Ok(entry)
}

